	err := tx.QueryRow(ctx, sqlVoiceUsageForPeriod, orgID, periodStart).Scan(&totalSeconds)
	if err != nil {
		return 0, fmt.Errorf("BillingRepository.GetVoiceUsageForPeriod: %w", err)
	}
	return totalSeconds, nil
}

