	secret := "test-webhook-secret-key"
	svc := service.NewBillingService(nil, nil, nil, secret)

	payload := []byte(`{"event_type":"payment_succeeded","content":{"payment_id":"pay_123"}}`)
	mac := hmac.New(sha256.New, []byte(secret))
