	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, c.baseURL+"/payments", bytes.NewReader(body))
	if err != nil {
		return nil, fmt.Errorf("hyperswitch: create request: %w", err)
	}
	c.setHeaders(httpReq)

